        private static void Add(ShelfLibrary library, string sectionName, string name, string id, string plugin, string panelText) {
            var guid = new Guid(id);
            var label = panelText == null ? name : name + " · " + panelText;
            if (library.Sections.SelectMany(s => s.Items).Any(i => i.ComponentId == guid && (panelText == null ? !i.IsRecipe : i.Name == label))) return;
            var section = library.Sections.FirstOrDefault(s => s.Title == sectionName);
            if (section == null) { section = new ShelfSection { Title = sectionName }; library.Sections.Add(section); }
            var item = new ShelfItem { ComponentId = guid, Name = label, Notes = plugin };
            if (panelText != null) { var panel = new GH_Panel(); panel.CreateAttributes(); panel.UserText = panelText; item = Recipes.Capture(panel); item.Name = label; item.Notes = "QuickConnection panel · " + panelText; }
            section.Items.Add(item);
        }
